const state={rows:[],status:"live",page:1,perPage:8,metric:"budget",view:"cards",source:"unavailable",privateTenders:{records:[],page:1,perPage:12,loaded:false,loading:false,fetchedAt:null},awards:{records:[],page:1,total:0,pageSize:10,loaded:false,loading:false,queued:false,filters:null,search:null,searchCache:new Map(),searchGeneration:0,lastFetchedAt:0},saved:new Set(JSON.parse(localStorage.getItem("tenderdesk-saved")||"[]"))};
