function unwrap(payload){if(Array.isArray(payload))return payload;for(const k of ["data","tenders","tenders_active","tenders_archived","active","archived","items","records","results","notices","content"]){if(Array.isArray(payload?.[k]))return payload[k];}if(payload&&typeof payload==="object"){const arr=Object.values(payload).find(v=>Array.isArray(v));if(arr)return arr;}return [];}
