function fillAwardSelect(id,options,firstLabel){const select=$(id),selected=select.value;select.innerHTML=`<option value="0">${firstLabel}</option>`+(options||[]).map(o=>`<option value="${escapeHtml(o.value)}">${escapeHtml(o.label)}</option>`).join("");if([...select.options].some(o=>o.value===selected))select.value=selected;}
function awardSearchParams(){const params=new URLSearchParams();for(const [id,key] of [["#award-nature","procurementTypeId.id"],["#award-ministry","ministryId.id"],["#award-method","procurementMethodId.id"],["#award-view-by","viewResultBy"]]){const value=$(id).value;if(value&&value!=="0")params.set(key,value);}return params;}
function awardCacheKey(){return awardSearchParams().toString();}
function awardSearchText(r){return [r.ministry,r.agency,r.reference,r.title,r.procuringEntity,r.procurementType,r.district,r.awardDate,r.supplier,r.supplierAddress,r.contractValue].join(" ").toLocaleLowerCase();}
function awardMatches(search){return [...search.pages.entries()].sort((a,b)=>a[0]-b[0]).flatMap(([,rows])=>rows).filter(r=>awardSearchText(r).includes(search.query));}
function privateRows(){const a=state.privateTenders,query=$("#private-search").value.trim().toLocaleLowerCase(),scope=$("#private-scope").value,status=$("#private-status-filter").value;return a.records.filter(r=>{const days=daysLeft(r.deadline);if(scope==="likely"&&r.organizationMatch!=="likely-private")return false;if(scope==="review"&&r.organizationMatch!=="review")return false;if(status==="open"&&days!==null&&days<0)return false;if(status==="expired"&&(days===null||days>=0))return false;if(query&&![r.id,r.sourceRecordId,r.title,r.organization,r.category,r.district,r.publicationSources.join(" ")].join(" ").toLocaleLowerCase().includes(query))return false;return true;}).sort((x,y)=>(daysLeft(x.deadline)??99999)-(daysLeft(y.deadline)??99999));}
function renderPrivateTenders(){const a=state.privateTenders,rows=privateRows(),pageCount=Math.max(1,Math.ceil(rows.length/a.perPage));a.page=Math.min(a.page,pageCount);const start=(a.page-1)*a.perPage,shown=rows.slice(start,start+a.perPage);$("#private-total").textContent=rows.length.toLocaleString();$("#private-nav-count").textContent=a.records.filter(r=>r.organizationMatch==="likely-private").length.toLocaleString();$("#private-updated").textContent=a.fetchedAt?`Updated ${new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit",timeZone:"Asia/Dhaka"}).format(new Date(a.fetchedAt))} BST`:a.loading?"Connecting to TenderBazar…":"—";$("#private-cards").innerHTML=shown.length?shown.map(r=>{const days=daysLeft(r.deadline),closed=days!==null&&days<0,match=r.organizationMatch==="likely-private"?"Likely private":"Needs review";return `<article class="tender-card ${closed?"is-closed":""}"><div class="card-top"><span class="card-id">ID: <b>${escapeHtml(r.id)}</b></span><span class="card-chip method-chip">${escapeHtml(r.category)}</span><span class="card-chip fund-chip private-match ${r.organizationMatch}">${match}</span></div><div class="card-agency"><span class="pin">⌖</span><b>${escapeHtml(r.district)}</b><span class="agency-divider">·</span><span>${escapeHtml(r.organization)}</span></div><div class="card-title-line"><a class="card-title private-title-link" href="${escapeHtml(r.sourceUrl)}" target="_blank" rel="noreferrer">${escapeHtml(r.title)}</a></div><div class="card-reference">TenderBazar ID ${escapeHtml(r.sourceRecordId)}${r.publicationSources.length?` · Published via ${escapeHtml(r.publicationSources.join(", "))}`:""}</div><div class="card-metrics"><div><small>DOCUMENT PRICE</small><b>${escapeHtml(r.documentPrice||"See source")}</b></div><div><small>SECURITY</small><b>${escapeHtml(r.securityAmount||"See source")}</b></div><div><small>EST. BUDGET</small><b>Not listed</b></div></div><div class="card-dates"><div><small>PUBLISHED</small><b>${escapeHtml(fmtDate(r.publicationDate))}</b></div><div class="time-left ${days!==null&&days<=5&&!closed?"urgent":""}"><small>STATUS</small><b>${closed?"Expired":days===null?"Check notice":"Open"}</b></div><div class="deadline-date"><small>DEADLINE</small><b>${escapeHtml(fmtDateTime(r.deadline))}</b></div></div><div class="private-source-links"><a class="card-official" href="${escapeHtml(r.sourceUrl)}" target="_blank" rel="noreferrer">↗ Open TenderBazar notice</a>${r.documentUrl?`<a class="private-image-link" href="${escapeHtml(r.documentUrl)}" target="_blank" rel="noreferrer">Open notice image ↗</a>`:""}</div></article>`;}).join(""):a.loading?'<div class="cards-empty"><b>Loading public notices…</b><p>Fetching TenderBazar’s featured list.</p></div>':a.loaded?'<div class="cards-empty"><b>No records match these filters</b><p>Try “All public featured” or adjust the search and status.</p></div>':'<div class="cards-empty"><b>TenderBazar is unavailable</b><p>Use Refresh to try loading the public list again.</p></div>';
const from=rows.length?start+1:0,to=Math.min(start+a.perPage,rows.length);$("#private-range").textContent=rows.length?`Showing ${from}–${to} of ${rows.length} public featured notices`:`0 matching notices`;$("#private-pagination").innerHTML=`<button class="page-btn" data-private-page="${Math.max(1,a.page-1)}" ${a.page<=1?"disabled":""} aria-label="Previous page">‹</button><span class="award-page-number">${a.page}</span><button class="page-btn" data-private-page="${Math.min(pageCount,a.page+1)}" ${a.page>=pageCount?"disabled":""} aria-label="Next page">›</button>`;}
let privateFetchPromise=null;async function fetchPrivateTenders({background=false}={}){const a=state.privateTenders;if(a.loading)return privateFetchPromise;a.loading=true;if(!background){$("#private-status").innerHTML='<span class="callout-icon">◷</span><span><b>Connecting to TenderBazar</b> Loading publicly visible featured notices…</span>';renderPrivateTenders();}privateFetchPromise=(async()=>{try{const response=await fetch("/api/private-tenders",{headers:{Accept:"application/json"},cache:"no-store",signal:AbortSignal.timeout(25000)});if(!response.ok)throw new Error(`TenderBazar request failed (${response.status})`);const payload=await response.json();a.records=Array.isArray(payload.records)?payload.records:[];a.fetchedAt=payload.fetchedAt;a.loaded=true;a.page=1;$("#private-status").innerHTML=`<span class="callout-icon success">✓</span><span><b>TenderBazar public feed connected</b> ${a.records.length.toLocaleString()} featured notices loaded. Verify details on the source record.</span><a href="https://www.tenderbazar.com/#1" target="_blank" rel="noreferrer">Open source ↗</a>`;renderPrivateTenders();}catch(error){if(!a.records.length){a.loaded=false;$("#private-status").innerHTML='<span class="callout-icon">!</span><span><b>TenderBazar is unavailable</b> The public featured list could not be loaded.</span><button class="callout-action" id="private-retry">Retry ↻</button>';$("#private-updated").textContent="Feed unavailable";}else if(!background){$("#private-status").innerHTML='<span class="callout-icon">!</span><span><b>Refresh failed</b> Showing the last records loaded in this session.</span>';}}finally{a.loading=false;renderPrivateTenders();privateFetchPromise=null;}})();return privateFetchPromise;}
$("#private-refresh").addEventListener("click",()=>fetchPrivateTenders());$("#private-search").addEventListener("input",()=>{state.privateTenders.page=1;renderPrivateTenders();});["#private-scope","#private-status-filter"].forEach(id=>$(id).addEventListener("change",()=>{state.privateTenders.page=1;renderPrivateTenders();}));$("#private-pagination").addEventListener("click",e=>{const button=e.target.closest("[data-private-page]");if(button&&!button.disabled){state.privateTenders.page=Number(button.dataset.privatePage);renderPrivateTenders();$("#private-cards").scrollIntoView({behavior:"smooth",block:"start"});}});$("#private-status").addEventListener("click",e=>{if(e.target.id==="private-retry")fetchPrivateTenders();});setInterval(()=>{if(document.visibilityState==="visible"&&!$("#private-page").hidden&&state.privateTenders.loaded)fetchPrivateTenders({background:true});},5*60*1000);
function renderAwards(){const a=state.awards,search=a.search,query=$("#award-search").value.trim().toLocaleLowerCase();let all=search&&search.query===query?search.matches:a.records;const totalPages=search?Math.max(1,Math.ceil(search.matches.length/a.pageSize)):Math.max(1,Math.ceil(a.total/a.pageSize));const page=Math.min(a.page,totalPages);if(page!==a.page)a.page=page;const records=search?all.slice((page-1)*a.pageSize,page*a.pageSize):all;$("#award-total").textContent=Number(a.total||0).toLocaleString();$("#award-nav-count").textContent=Number(a.total||0).toLocaleString();$("#award-page-number").textContent=String(page);$("#award-updated").textContent=a.fetchedAt?`Updated ${new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit",timeZone:"Asia/Dhaka"}).format(new Date(a.fetchedAt))} BST`:a.loading?"Connecting to BPPA…":"—";$("#award-rows").innerHTML=records.map(r=>`<tr><td class="award-description"><b>${escapeHtml(r.ministry)}${r.agency?` · ${escapeHtml(r.agency)}`:""}</b><span class="award-reference">${escapeHtml(r.reference)}</span><strong>${escapeHtml(r.title)}</strong><small>Advertised ${escapeHtml(r.advertisementDate||"—")}</small></td><td class="award-entity"><span>${escapeHtml(r.procuringEntity)}</span><small>${escapeHtml(r.procurementType)}</small></td><td>${escapeHtml(r.district)}</td><td class="award-supplier"><b>${escapeHtml(r.supplier)}</b><small>${escapeHtml(r.supplierAddress)}</small></td><td class="award-value">${escapeHtml(r.contractValue)}</td><td>${escapeHtml(r.awardDate)}</td><td><a class="row-open" href="${escapeHtml(r.detailUrl)}" target="_blank" rel="noreferrer" aria-label="Open BPPA award detail">↗</a></td></tr>`).join("");$("#award-empty").hidden=records.length!==0||a.loading||!a.loaded||Boolean(search?.searching);if(search?.query==query){$("#award-empty").querySelector("b").textContent=search.searching?"Searching the full BPPA register…":"No BPPA awards match this search";$("#award-empty").querySelector("p").textContent=search.searching?"Matches will appear as official pages are scanned.":"Try another supplier, title, ministry or reference.";}const from=all.length?(page-1)*a.pageSize+1:0,to=Math.min(page*a.pageSize,all.length);$("#award-range").textContent=search&&search.query===query?search.searching?`Searching all BPPA awards · scanned ${search.scanned.toLocaleString()} of ${search.totalPages.toLocaleString()} pages · ${all.length.toLocaleString()} matches so far`:search.error?`${all.length.toLocaleString()} matches · scan paused: ${search.error}`:`${all.length.toLocaleString()} matches across ${Number(a.total).toLocaleString()} official awards`:a.loaded?a.total?`Showing ${(a.page-1)*a.pageSize+1}–${Math.min(a.page*a.pageSize,a.total)} of ${Number(a.total).toLocaleString()} official awards`:"No official awards match these filters":"Loading official results…";$("#award-prev").disabled=a.loading||page<=1;$("#award-next").disabled=a.loading||(search?!search.searching&&page>=totalPages:page*a.pageSize>=a.total);}
async function fetchAwards(options={}){const a=state.awards;if(a.loading){if(!options.background)a.queued=true;return;}a.loading=true;$("#award-error").hidden=true;if(!options.background){$("#award-status").innerHTML='<span class="callout-icon">◷</span><span><b>Connecting to BPPA</b> Loading published contract awards…</span>';renderAwards();}const params=awardSearchParams(),page=options.background&&a.search?0:a.page-1;params.set("page",String(page));try{const response=await fetch(`/api/contract-awards?${params}`,{headers:{Accept:"application/json"},cache:"no-store",signal:AbortSignal.timeout(25000)});if(!response.ok)throw new Error(`BPPA request failed (${response.status})`);const payload=await response.json();if(!options.background||!a.search)a.records=Array.isArray(payload.records)?payload.records:[];a.total=Number(payload.total)||0;a.pageSize=Number(payload.pageSize)||10;a.fetchedAt=payload.fetchedAt;a.lastFetchedAt=Date.now();a.loaded=true;a.filters=payload.filters||a.filters;const key=awardCacheKey();let cache=a.searchCache.get(key);if(!cache||Date.now()-cache.updatedAt>5*60*1000){cache={pages:new Map(),total:a.total,pageSize:a.pageSize,totalPages:Math.max(1,Math.ceil(a.total/a.pageSize)),updatedAt:Date.now()};a.searchCache.set(key,cache);}cache.pages.set(page,Array.isArray(payload.records)?payload.records:[]);cache.total=a.total;cache.pageSize=a.pageSize;cache.totalPages=Math.max(1,Math.ceil(a.total/a.pageSize));if(!options.background)cache.updatedAt=Date.now();if(a.filters){fillAwardSelect("#award-nature",a.filters.natures,"All natures");fillAwardSelect("#award-ministry",a.filters.ministries,"All ministries");fillAwardSelect("#award-method",a.filters.methods,"All types");}if(!options.background)$("#award-status").innerHTML=`<span class="callout-icon success">✓</span><span><b>BPPA register connected</b> ${a.total.toLocaleString()} public awards · Auto-refreshes every 5 minutes while the awards page is open.</span><a href="https://bppa.gov.bd/contract-award/contract-award-list.html" target="_blank" rel="noreferrer">Open BPPA ↗</a>`;$("#award-error").hidden=true;}catch(error){if(!options.background){a.records=[];a.total=0;a.loaded=false;$("#award-error-message").textContent="The official BPPA award list is temporarily unavailable. Please try again shortly.";$("#award-error").hidden=false;$("#award-status").innerHTML='<span class="callout-icon">!</span><span><b>BPPA is unavailable</b> No example records are shown.</span>';}}finally{a.loading=false;renderAwards();if(a.queued){a.queued=false;fetchAwards();}}}
async function runAwardSearch(query,generation){const a=state.awards,key=awardCacheKey();let cache=a.searchCache.get(key);if(!cache||Date.now()-cache.updatedAt>5*60*1000){cache={pages:new Map(),total:a.total,pageSize:a.pageSize||10,totalPages:Math.max(1,Math.ceil(a.total/(a.pageSize||10))),updatedAt:Date.now()};a.searchCache.set(key,cache);}const search={query,generation,pages:cache.pages,totalPages:cache.totalPages,scanned:cache.pages.size,matches:[],searching:true,error:""};a.search=search;a.page=1;search.matches=awardMatches(search);renderAwards();while(search.scanned<search.totalPages){if(generation!==a.searchGeneration)return;let start=0;while(start<search.totalPages&&search.pages.has(start))start++;if(start>=search.totalPages)break;let count=0;while(count<8&&start+count<search.totalPages&&!search.pages.has(start+count))count++;const params=awardSearchParams();params.set("scanStart",String(start));params.set("scanCount",String(count));try{const response=await fetch(`/api/contract-awards?${params}`,{headers:{Accept:"application/json"},cache:"no-store",signal:AbortSignal.timeout(35000)});if(!response.ok)throw new Error(`BPPA scan request failed (${response.status})`);const payload=await response.json();if(generation!==a.searchGeneration)return;search.totalPages=Number(payload.totalPages)||search.totalPages;search.scanned=0;for(const batch of payload.pages||[]){search.pages.set(Number(batch.page),batch.records||[]);}search.scanned=search.pages.size;cache.total=Number(payload.total)||cache.total;cache.totalPages=search.totalPages;cache.pageSize=Number(payload.pageSize)||cache.pageSize;cache.updatedAt=Date.now();a.total=cache.total;a.pageSize=cache.pageSize;search.matches=awardMatches(search);renderAwards();}catch(error){if(generation!==a.searchGeneration)return;search.error="Official pages could not be reached. Press Refresh to retry.";search.searching=false;renderAwards();return;}}if(generation!==a.searchGeneration)return;search.searching=false;search.matches=awardMatches(search);renderAwards();}
function scheduleAwardSearch(){const a=state.awards,query=$("#award-search").value.trim().toLocaleLowerCase();clearTimeout(a.searchTimer);const generation=++a.searchGeneration;if(!query){a.search=null;a.page=1;renderAwards();return;}const cache=a.searchCache.get(awardCacheKey());if(cache&&Date.now()-cache.updatedAt>5*60*1000)a.searchCache.delete(awardCacheKey());a.search=null;a.page=1;renderAwards();a.searchTimer=setTimeout(()=>runAwardSearch(query,generation),180);}
$("#award-refresh").addEventListener("click",()=>{const a=state.awards;a.searchGeneration++;a.search=null;a.page=1;a.searchCache.clear();fetchAwards().then(scheduleAwardSearch);});$("#award-retry").addEventListener("click",fetchAwards);$("#award-prev").addEventListener("click",()=>{if(state.awards.page>1){state.awards.page--;if(state.awards.search)renderAwards();else fetchAwards();}});$("#award-next").addEventListener("click",()=>{const a=state.awards;if(a.search){if(a.page*a.pageSize<a.search.matches.length||a.search.searching){a.page++;renderAwards();}}else if(a.page*a.pageSize<a.total){a.page++;fetchAwards();}});$("#award-search").addEventListener("input",scheduleAwardSearch);["#award-nature","#award-ministry","#award-method","#award-view-by"].forEach(id=>$(id).addEventListener("change",()=>{state.awards.page=1;state.awards.searchGeneration++;state.awards.search=null;fetchAwards().then(()=>scheduleAwardSearch());}));$("#award-reset").addEventListener("click",()=>{$("#award-search").value="";$("#award-nature").value="0";$("#award-ministry").value="0";$("#award-method").value="0";$("#award-view-by").value="awardNotificationDate";state.awards.page=1;state.awards.searchGeneration++;state.awards.search=null;state.awards.searchCache.clear();fetchAwards();});
